import {
  type AudioComponentData,
  type FileComponentData,
  type ImageComponentData,
  MediaUploadErrorKey,
  type UpdateEntityFileUploadFunc,
  type VideoComponentData,
} from './../ricos-content/index.js';
import type { RicosServices } from './../ricos-types/index.js';

import { getHighestQualityVideo } from './get-highest-quality-video.js';
import { getMediaFileType } from './get-media-file-type.js';
import { getUploadError } from './get-upload-error.js';
import { MediaType } from './request-service-provider/consts.js';
import { createUploadFn } from './request-service-provider/media-manager-uploader.js';
import type {
  MediaManagerSDKError,
  RawImageData,
  RawVideoData,
} from './request-service-provider/upload-types.js';
import { withFileSizeLimitation } from './with-file-size-limitation.js';

export type MediaUploadFn = ReturnType<typeof createMediaUploadFn>;

export const createMediaUploadFn = (
  services: Pick<RicosServices, 'wixInstance' | 'editorProps'>
) => {
  const { metaSiteId, uid, siteOwnerId } = services.wixInstance();

  if (!metaSiteId) {
    return undefined;
  }

  const upload = createUploadFn(services);

  const handleUploadError = (
    error: MediaManagerSDKError,
    updateEntity: UpdateEntityFileUploadFunc<
      ImageComponentData & VideoComponentData & AudioComponentData & FileComponentData
    >
  ) => {
    const isOwner = siteOwnerId === uid;
    const mediaUploadError = getUploadError(error, metaSiteId, isOwner);
    updateEntity({ error: mediaUploadError });
  };

  const imageUpload = (
    file: File,
    updateEntity: UpdateEntityFileUploadFunc<ImageComponentData>
  ) => {
    return upload(file, MediaType.IMAGE)
      .then(({ file_name, original_file_name, height, width }: RawImageData) => {
        updateEntity({
          data: {
            id: file_name,
            height,
            width,
            original_file_name,
            file_name,
          },
        });
      })
      .catch((error: MediaManagerSDKError) => {
        return handleUploadError(error, updateEntity);
      });
  };

  const videoUpload = (
    file: File,
    updateEntity: UpdateEntityFileUploadFunc<VideoComponentData>
  ) => {
    return upload(file, MediaType.VIDEO)
      .then(({ file_output: { video, image } }: RawVideoData) => {
        updateEntity({
          data: {
            pathname: getHighestQualityVideo(video).url,
            thumbnail: {
              pathname: image[0].url,
              width: image[0].width,
              height: image[0].height,
            },
            title: file.name,
          },
        });
      })
      .catch((error: MediaManagerSDKError) => handleUploadError(error, updateEntity));
  };

  const getUnsupportedExtensionError = (fileName: string) => {
    return {
      key: MediaUploadErrorKey.UNSUPPORTED_EXTENSION,
      args: { extension: fileName.split('.').pop()?.toLowerCase() || '' },
    };
  };

  const galleryUpload = (
    file: File,
    updateEntity: UpdateEntityFileUploadFunc<ImageComponentData | VideoComponentData>
  ) => {
    const fileType = getMediaFileType(file.name);
    if (fileType === MediaType.IMAGE) {
      return imageUpload(file, updateEntity as UpdateEntityFileUploadFunc<ImageComponentData>);
    } else if (fileType === MediaType.VIDEO) {
      return videoUpload(file, updateEntity as UpdateEntityFileUploadFunc<VideoComponentData>);
    } else {
      return updateEntity({
        error: getUnsupportedExtensionError(file.name),
      });
    }
  };

  return withFileSizeLimitation(galleryUpload, services.editorProps.fileUploadSizeLimit);
};
