// lodash.debounce for the options our call sites use: trailing edge by default,
// optional leading edge (where — like lodash — the trailing call only fires if
// the function was invoked again after the leading one), and a `cancel` method
// for unmount cleanup.
export function debounce<Args extends unknown[]>(
  fn: (...args: Args) => void,
  wait = 0,
  options?: { leading?: boolean }
): ((...args: Args) => void) & { cancel: () => void } {
  let timer: ReturnType<typeof setTimeout> | undefined;
  let pendingTrailing = false;
  let lastArgs: Args | undefined;
  const debounced = (...args: Args) => {
    lastArgs = args;
    if (options?.leading && timer === undefined) {
      pendingTrailing = false;
      fn(...args);
    } else {
      pendingTrailing = true;
    }
    clearTimeout(timer);
    timer = setTimeout(() => {
      timer = undefined;
      if (pendingTrailing) {
        pendingTrailing = false;
        fn(...(lastArgs as Args));
      }
    }, wait);
  };
  debounced.cancel = () => {
    clearTimeout(timer);
    timer = undefined;
    pendingTrailing = false;
  };
  return debounced;
}
