import type { WixClient } from '@wix/sdk/client';
import React from 'react';

export type GetWixClientPromise = () => Promise<WixClient>;

export const useGetWixClientPromise = (instance: string, wixClient?: WixClient) => {
  const wixClientGetter: GetWixClientPromise | undefined = React.useMemo(
    () => (wixClient ? () => Promise.resolve(wixClient) : undefined),
    [wixClient]
  );

  const instanceGetter = React.useMemo(() => {
    let wixClientPromise: ReturnType<GetWixClientPromise>;
    return () => {
      if (wixClientPromise) {
        return wixClientPromise;
      }

      wixClientPromise = import(
        /* webpackChunkName: "wix-ricos-sdk-client" */ '@wix/sdk/client'
      ).then(clientSdk => {
        return clientSdk.createClient({
          auth: {
            getAuthHeaders: () => ({ headers: { Authorization: instance } }),
          },
        });
      });
      return wixClientPromise;
    };
  }, [instance]);

  return React.useMemo(
    () => ({ getWixClientPromise: wixClientGetter ?? instanceGetter }),
    [wixClientGetter, instanceGetter]
  );
};
